CREATE TRIGGER application_draft_discard_update
AFTER UPDATE OF generation ON application_draft_generation
BEGIN
  DELETE FROM application_draft WHERE user_id = NEW.user_id;
END;

CREATE TRIGGER signup_recurring_window_update
BEFORE UPDATE OF status, event_id, user_id, manual_medic, manual_new ON signup WHEN NEW.status = 'confirmed'
BEGIN
  SELECT RAISE(ABORT, 'recurring_signup_window') WHERE EXISTS (
    SELECT 1 FROM event e JOIN patrol_series ps ON ps.id = e.series_id
    WHERE e.id = NEW.event_id AND e.starts_at >= ps.generation_until
  );
END;

CREATE TRIGGER recurring_occurrence_no_delete
BEFORE DELETE ON event WHEN OLD.series_id IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'recurring_occurrence_tombstone');
END;

CREATE TRIGGER patrol_series_identity_immutable
BEFORE UPDATE OF id, first_date, time_zone ON patrol_series
WHEN NEW.id IS NOT OLD.id OR NEW.first_date IS NOT OLD.first_date OR NEW.time_zone IS NOT OLD.time_zone
BEGIN
  SELECT RAISE(ABORT, 'patrol_series_identity_immutable');
END;

CREATE TRIGGER event_capacity_update
BEFORE UPDATE OF spots ON event
BEGIN
  SELECT RAISE(ABORT, 'capacity_below_signups')
  WHERE NEW.spots < (SELECT count(*) FROM signup WHERE event_id = OLD.id AND status = 'confirmed');
END;

CREATE TRIGGER event_orientation_capacity_update
BEFORE UPDATE OF type, includes_orientation, spots, min_medic_spots, min_new_volunteer_spots, max_new_volunteers, unregister_minutes, starts_at, meeting_point, meeting_point_url, open, hidden ON event
BEGIN
  SELECT RAISE(ABORT, 'event_invalid_unregister_minutes') WHERE
    typeof(NEW.unregister_minutes) != 'integer' OR NEW.unregister_minutes NOT BETWEEN 0 AND 10080;
  SELECT RAISE(ABORT, 'event_invalid_limits') WHERE
    typeof(NEW.min_medic_spots) != 'integer' OR NEW.min_medic_spots NOT BETWEEN 0 AND 100
    OR typeof(NEW.min_new_volunteer_spots) != 'integer' OR NEW.min_new_volunteer_spots NOT BETWEEN 0 AND 100
    OR typeof(NEW.max_new_volunteers) != 'integer' OR NEW.max_new_volunteers NOT BETWEEN NEW.min_new_volunteer_spots AND 100;
  SELECT RAISE(ABORT, 'event_minimum_capacity') WHERE NEW.cancelled_at IS NULL AND NEW.spots < NEW.min_medic_spots
    + CASE WHEN coalesce(NEW.includes_orientation, NEW.type = 'orientation') THEN NEW.min_new_volunteer_spots ELSE 0 END;
END;

